int main(int argc, char **argv) {
    int n = argc > 1 ? atoi(argv[1]) : 100000;
    char *s = malloc((size_t)n + 1);
    int64_t acc = 0;
    int len = 0;
    for (int i = 0; i < n; i++) {
        s[len++] = (char)('a' + (i % 26));
        acc = (acc + len) % 1000003;
    }
    s[len] = 0;
    printf("%lld\n", (long long)((acc + strlen(s)) % 1000003));
    free(s);
}

