#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
static int64_t fibonacci(int64_t value){if(value<2)return value;return fibonacci(value-1)+fibonacci(value-2);}
int main(int argc,char**argv){int64_t n=argc>1?atoll(argv[1]):100,acc=0;for(int64_t i=0;i<n;++i)acc=(acc+fibonacci(20+i%2))%1000003;printf("%" PRId64 "\n",acc);}

function fibonacci(value: Int): Int {
    if value < 2 { return value }
    return fibonacci(value: value - 1) + fibonacci(value: value - 2)
}
@main {
    state i: Int(0)
    state acc: Int(0)
    while i < 100 {
        acc: (acc + fibonacci(value: 20 + i % 2)) % 1000003
        i: i + 1
    }
    return acc % 251
}

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
static inline int64_t choose(int64_t lhs, int64_t rhs, int flag) { return flag ? lhs : rhs; }
int main(int argc, char **argv) {
    int64_t n = argc > 1 ? atoll(argv[1]) : 1000000;
    int64_t acc = 0;
    for (int64_t i = 0; i < n; i++) acc = (acc + choose(i, i + 1, (int)(i & 1))) % 1000003;
    printf("%lld\n", (long long)acc);
}

function choose(lhs: Int, rhs: Int, flag: Bool): Int {
    if flag {
        return lhs
    }
    return rhs
}

@main {
    let n: Int(1000000)
    state i: Int(0)
    state acc: Int(0)
    while i < n {
        acc: (acc + choose(lhs: i, rhs: i + 1, flag: i % 2 == 1)) % 1000003
        i: i + 1
    }
    return acc % 251
}
